actions.script:
// make sure SQL comes in secure parameter (body, etc no URL)
const sqlScript = ec.web.secureRequestParameters.sql
if (sqlScript && groupName) {
    // as in Java, split on semicolons; a result set is read and not shown (see SqlRunner.xml to show one)
    const sqlList = String(sqlScript).split(';')
    messageList = []
    for (const sql of sqlList) {
        if (!sql.trim()) continue
        try {
            const result = ec.entity.runSqlStatement(String(groupName), sql, 1)
            if (result.rowsAffected != null) messageList.push(ec.resource.expand('Query altered ${rowsAffected} rows.', '', {rowsAffected: result.rowsAffected}))
        } catch (e) {
            messageList.push(String(e))
            ec.logger.log(200, "Error running SQL query in SqlRunner", e)
        }
    }
}
